import itertools
import review_remaining605 as r
b=r.folder(50)
feasible=[]
for a,bb,d in itertools.product(range(1,53),range(1,49),range(1,32)):
 rem=1000-12*a-10*bb-2*d
 if rem%3==0 and 1<=rem//3<=150:feasible.append((10*a+7*bb+rem+d,a,bb,rem//3,d))
best=max(x[0] for x in feasible);winners=[x for x in feasible if x[0]==best]
assert winners==[(905,44,2,150,1)]
byA={a:max(x[0] for x in feasible if x[1]==a) for a in range(44,49)}
schedules=[]
days=list(range(7,15));choices=[list(itertools.combinations('ABC',2 if d in [9,13] else 1)) for d in days]
for seq in itertools.product(*choices):
 if 'B' in seq[4] or 'C' in seq[6] or any(set(x)&set(y) for x,y in zip(seq,seq[1:])):continue
 schedules.append(seq)
cc=[sum('C' in x for x in seq) for seq in schedules];assert (min(cc),max(cc))==(3,4)
scores=list(itertools.combinations_with_replacement([80,90,100],5))
aa=[s for s in scores if min(s)==80 and max(s)==100 and sum(s)==460]
bs=[s for s in scores if min(s)==80 and max(s)==90]
cs=[s for s in scores if max(s)==90 and sum(s)==440]
ds=[s for s in scores if min(s)==80 and max(s)==100]
assert all(sum(s[1:-1])==280 for s in aa) and cs==[(80,90,90,90,90)]
assert max(sum(s[1:-1]) for s in bs)==270
assert max(sum(s[1:-1]) for s in ds)==300
r.write(b/'pre-reveal-exact-models.json',dict(status='PASS',gemFeasibleCount=len(feasible),gemWinners=winners,gemBestForOptions=byA,dutySchedules=schedules,dutyCCounts=sorted(set(cc)),ratingConfigurations=dict(A=aa,B=bs,C=cs,D=ds)))
rows=[
(1,'가격을 무게에서 뺀 손실은 A당2, B당3, C당0, D당1이다. 정확히1000g, A1~52/B1~48/C1~150/D1~31의 정수 조건을 대입하면 (A44,B2,C150,D1)이 528+20+450+2=1000g, 440+14+450+1=905만원으로 유일최대다. C를 모두 넣고 B를 무조건1로 고정하면 D6이라903만원으로 더 작아 그 탐욕법은 안된다. A44~48별 최대도 전수모형으로 비교하여①.', ['A44/B2/C150/D1이 정확히1000g이고905만원으로 전역 최댓값이다.','A45에서 가능한 최댓값도905만원보다 작아 최적 개수가 아니다.','A46을 강제하면 C가 줄어 전체 금액이905만원에 못 미친다.','A47의 모든 정수조합도 유일최대905만원보다 작다.','A48의 조합은 단위가격 높은 C를 더 빼야 하므로 최적이 아니다.']),
(3,'13일은 丙휴가여서甲乙 두명이며12와14는丙이다. 11은乙출장이고12丙과연속불가여서甲이다. 9의두명에빠진한명이8/10을모두서야하므로그사람은乙또는丙이다. 乙이면9甲丙/8,10乙이라丙3일이고7을丙으로두면4일이다. 丙이면8/10/12/14의4일,7은丙불가다. 따라서 최소3 최대4이고 유효배치 전수열거와도 일치하여③.', ['최솟값은3이므로2로 제시한 이 조합은 틀리다.','최댓값4는 맞지만 최솟값2는 불가능하다.','13일甲乙로12/14丙이 강제되며 가능한 丙일수는3또는4다.','최솟값3은 맞지만 연속당직금지로 최댓값5는 불가능하다.','3일인 배치가 존재하고5일은 불가능해 두 수 모두 틀렸다.']),
(3,'A전체합460에서최고100최저80하나씩빼280점이다. 남은3인모두90이면270이므로①아니다. C평균88총440최고90이어서90네개80한개,남은270점이다. B는최고90이므로남은최대270으로A280을넘지못한다. D는최고100최저80을포함하여남은합240~300이고280으로A와동점가능하지만B/C는안되므로2차최대2업체다. ③만참.', ['A중간3명의 합은280이므로 세명모두90인270이 아니다.','C는90네명과80한명이어서 하등급은1명이다.','B남은3인점수는 최대270이므로A의고정280에 못 미친다.','C270이A280보다작으므로 선정가능성이 없다.','A와D만 최고동점가능하고B/C가A를못따라3업체는불가다.']),
(1,'초급戊는 점수계산 전에 제외한다. 기술/경력/건수/금액점수는甲2+7+4+5=18,乙3+7+4+4=18,丙4+6+2+5=17,丁4+6+3+5=18이다. 각 구간은이상포함/미만제외라9년은7점,8년은6점,12건은4점,10건은3점이다. 18점동점甲乙丁 중 실적건수13,12,10을비교해甲을선정하므로①.', ['甲은18점동점자 중 실적13건으로 가장 많아선정된다.','乙도18점이지만12건으로甲의13건보다적다.','丙은17점이라최고점18점에못미친다.','丁은18점이지만실적10건으로甲보다적다.','戊는초급이어서경력과실적에관계없이선정에서제외한다.']),
(4,'기준일2023년1월1일에연령과독립경영3조건을모두본다. 甲은1980년5월생으로42세이며6개월을빼도40세를넘는다. 乙은경영주등록이1월3일로기준일뒤여서예정자도아니다. 丙은2018년2월3일부터독립경영해3년초과다. 丁은33세에서군복무24개월을빼도범위내이고2021년1월5일부터실제경영이라3년이하,농지/등록도충족한다. 戊는등록없어예정자아니다.④.', ['甲은군복무6개월을제외해도40세를초과한다.','乙은기준일1월1일에경영주미등록이므로예정자요건도못갖췄다.','丙은2018년부터독립경영하여3년을초과했다.','丁은연령범위와본인농지/등록/직접영농및3년이하를모두충족한다.','戊는경영주등록이없어서독립경영예정자로도볼수없다.']),
(2,'관광효과=직접+간접+유발,일차=직접,이차=간접+유발이다. ㄱ은유발을빼면직접+간접이라틀리고,ㄴ은관광객이식당에직접지급한식대로직접효과라틀린다. ㄷ의나누어지는값은분자이며일반승수분자는총효과=일차+이차가맞다. 일반승수분모는최초관광지출이고비율승수분모가직접효과인점을분리한다. ㄷ만②.', ['ㄱ은간접효과가남는점을누락하여틀렸다.','ㄷ의분자는직접과간접과유발의합으로일차+이차와같다.','ㄱ도틀리고식대를유발로본ㄴ도틀려둘다불가다.','ㄷ은맞지만식대는직접효과라ㄴ이틀렸다.','ㄱㄴ은각각잔여간접효과/직접식대분류를잘못하여모두참은아니다.']),
(3,'직접효과D,최초지출E라두면D=E/2이고간접D+10,유발2D,총효과4D+10이다. 일반승수2.5=(4D+10)/(2D)이므로5D=4D+10, D=10억원이다. 총효과50억원을D10억원으로나눈비율승수5다. 역대입최초20/직접10/간접20/유발20/총50으로일반2.5와비율5를확인하므로③.', ['직접효과5이면일반승수가3이되어2.5조건과어긋난다.','직접10은맞지만비율승수는50/10=5여서4가아니다.','직접10억원이고최초20억원,총50억원으로비율승수5다.','직접20이면총90/최초40=2.25로주어진일반2.5와다르다.','직접20도아니고비율승수6도조건을충족하지못한다.']),
(3,'공연장등록권자는소재지시장군수구청장이고도지사가아니다. 폐업미신고는사실확인뒤직권말소가능이다. 연소자는18세미만뿐아니라고교재학생을포함하므로18세고등학생도연소자이고약물남용자극은유해공연물,벌금상한3000만원가능하여③. 암표벌칙의주체는판매자라구매자에확장못한다. 공연장외500명은1000명이상준용조건에못미친다.', ['A도지사가아니라공연장소재지B군수에게등록한다.','폐업사실을확인한후직권말소할수있으므로불가능은틀리다.','18세고교생도연소자이며약물남용자극공연관람은3000만원이하벌금가능이다.','규정은암표판매자를처벌하므로구매자丁의벌금근거가아니다.','공연장외500명은1000명이상피난안내도준용기준에못미친다.']),
(5,'선박소유자의국적이나법인설립준거법이등록대상을정한다. 국내법인만가능하고항로는국내외또는외국외국만가능하다. 등록순서는지방청장의선박원부/국적증서가먼저,장관의국제선박등록부/국제선박등록증이나중이다. 구조변경등등록사항이바뀌면그날부터1개월이내장관에게변경등록신청하므로⑤. ①국내간②외국법인③순서역전④원부주체혼동은틀린다.', ['부산과인천은둘다국내항이어서국제선박허용항로가아니다.','외국법설립상사법인은대한민국법률설립조건에맞지않는다.','국적증서와선박원부절차는국제선박등록전에밟아야한다.','장관이등록하는것은국제선박등록부이며선박원부는지방청장업무다.','구조변경은등록사항변경이므로발생일부터1개월이내장관에게신청한다.']),
(1,'처음면허면3개월내청소후종료일기준주기를잰다. 매생이지주망식은5년으로10년면허기간에초기와5년후최소2번이필요해①. 방어3년과우렁쉥이4년혼합은단기3년이다. 동일신규면허예외는기존마지막청소일부터주기계속이가능해3개월을강제못한다. 6ha계산300만원은회당상한250으로제한한다. 미더덕4년은첫청소2021년3월까지했다면다음2025년이며명령과불이행기간도필요해2024년자동부과아니다.', ['최초3개월내와그로부터5년이내에청소하므로10년간최소2번필요하다.','혼합주기는3년과4년중짧은3년으로4년이아니다.','동일신규면허는기존마지막청소일에서주기를이어갈수있는예외다.','계산액300만원이어도1회상한250만원을넘길수없다.','4년주기기산점은첫청소완료일이며명령불이행절차없이는자동부과할수없다.'])]
assert len(rows)==10 and not (b/'own-solves.json').exists()
r.write(b/'own-solves.json',[dict(id=q['id'],answer=a,reasoning=s,optionReasons=o) for q,(a,s,o) in zip(r.batch(50),rows)])
r.write(b/'sample.json',dict(sample=[dict(id=q['id']) for q in r.batch(50)]))
